# Build 6 7x7 tiles in row-major frame order; each interior is 5x5 source with holes filled by frame color.
def tile(frame, inner, holes):
    a=[[frame]*7 for _ in range(7)]
    for r in range(5):
        for c in range(5): a[r+1][c+1] = frame if (r,c) in holes else inner
